{
  "findings": [
    {
      "check_id": "CKV_GCP_25",
      "title": "Ensure Kubernetes Cluster is created with Private cluster enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "The Kubernetes cluster is not created with a private cluster enabled, potentially exposing it to unnecessary public access."
    },
    {
      "check_id": "AVD-GCP-0056",
      "title": "Cluster does not have a network policy enabled.",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "The cluster lacks a network policy, allowing unrestricted inter-cluster communication."
    },
    {
      "check_id": "CKV_GCP_23",
      "title": "Ensure Kubernetes Cluster is created with Alias IP ranges enabled",
      "resource": "google_container_cluster.k8sexample",
      "severity": "MEDIUM",
      "explanation": "The Kubernetes cluster is not created with Alias IP ranges enabled, which is recommended for proper IP address management."
    }
  ],
  "patched_code": "resource "google_container_cluster" "k8sexample" {
  name               = "${var.vault_user}-k8s-cluster"
  description        = "example k8s cluster"
  zone               = "${var.gcp_zone}"
  initial_node_count = "${var.initial_node_count}"
  enable_kubernetes_alpha = "true"
  enable_legacy_abac = "true"
  private_cluster_config {
    enable_private_nodes    = true
    enable_private_endpoint = false
    master_ipv4_cidr_block  = "172.16.0.0/28"
  }
  master_auth {
    username = "${var.master_username}"
    password = "${var.master_password}"
    client_certificate_config {
      issue_client_certificate = false
    }
  }
  node_config {
    machine_type = "${var.node_machine_type}"
    disk_size_gb = "${var.node_disk_size}"
    oauth_scopes = [
      "https://www.googleapis.com/auth/compute",
      "https://www.googleapis.com/auth/devstorage.read_only",
      "https://www.googleapis.com/auth/logging.write",
      "https://www.googleapis.com/auth/monitoring"
    ]
  }
  network_policy {
    enabled = true
  }
  ip_allocation_policy {
    cluster_secondary_range_name = "pods"
    services_secondary_range_name = "services"
  }
}",
  "fix_summary": "Enabled private cluster configuration, disabled client certificate issuance, enabled network policy, and enabled alias IP ranges for the Kubernetes cluster."
}
